use std::ops::Range;

use mesh_common::span::Span;

/// Where the text of a generated file came from in the file it was
/// generated from, as `meshc test` makes a program of a `.test.mpl` file:
/// the file's text, with ranges of it replaced, then text of its own.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct SourceMap {
    /// The replaced ranges, in order.
    splices: Vec<Splice>,
    /// The length of the file's text.
    source_len: usize,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Splice {
    /// The range of the file's text that was replaced.
    source: Range<usize>,
    /// Where its replacement is in the generated text.
    generated: Range<usize>,
}

/// Where a span of generated text is in the file it was generated from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Origin {
    /// The span's text is the file's, unchanged, here.
    Exact(Span),
    /// The span is or crosses generated text: this is the file's text it
    /// was generated from, or the end of the file for text added after it.
    Near(Span),
}

impl Origin {
    pub fn span(self) -> Span {
        match self {
            Origin::Exact(span) | Origin::Near(span) => span,
        }
    }
}

/// Where an offset of generated text is.
enum Place {
    /// In text copied from the file: the copy after `splice` replacements,
    /// at this offset of the file.
    Copied { after: usize, at: usize },
    /// Inside the replacement of this splice.
    Replaced(usize),
    /// In text added after the file's.
    Added,
}

impl SourceMap {
    /// The map of a file `source_len` bytes long, its text generated by
    /// replacing each range in `replaced` (in order, none overlapping) with
    /// text that many bytes long; text added after it maps to its end.
    pub fn new(
        source_len: usize,
        replaced: impl IntoIterator<Item = (Range<usize>, usize)>,
    ) -> Self {
        let mut splices = Vec::new();
        let mut shift = 0isize;
        for (source, len) in replaced {
            debug_assert!(
                splices
                    .last()
                    .is_none_or(|last: &Splice| last.source.end <= source.start),
                "replaced ranges are ordered and disjoint"
            );
            let start = source.start.checked_add_signed(shift).unwrap_or(0);
            shift += len as isize - source.len() as isize;
            splices.push(Splice {
                source,
                generated: start..start + len,
            });
        }
        SourceMap {
            splices,
            source_len,
        }
    }

    /// Where `span` of the generated text is in the file.
    pub fn origin(&self, span: Span) -> Origin {
        let (start, end) = (span.start as usize, span.end as usize);
        let exact = match (self.place(start, false), self.place(end, true)) {
            (Place::Copied { after, at }, Place::Copied { after: same, .. }) if after == same => {
                Some(at..at + (end - start))
            }
            _ => None,
        };
        if let Some(range) = exact {
            return Origin::Exact(Span::new(range.start as u32, range.end as u32));
        }
        let start = self.near(start, false);
        let end = self.near(end, true).max(start);
        Origin::Near(Span::new(start as u32, end as u32))
    }

    /// Where `offset` is. At the boundary of a copy and the replacement
    /// after it, a span's `end` is in the copy and its start in the
    /// replacement.
    fn place(&self, offset: usize, end: bool) -> Place {
        let mut copied_from = (0, 0);
        for (index, splice) in self.splices.iter().enumerate() {
            let in_copy = if end {
                offset <= splice.generated.start
            } else {
                offset < splice.generated.start
            };
            if in_copy {
                return Place::Copied {
                    after: index,
                    at: copied_from.1 + (offset - copied_from.0),
                };
            }
            if offset < splice.generated.end {
                return Place::Replaced(index);
            }
            copied_from = (splice.generated.end, splice.source.end);
        }
        let at = copied_from.1 + (offset - copied_from.0);
        if at <= self.source_len {
            Place::Copied {
                after: self.splices.len(),
                at,
            }
        } else {
            Place::Added
        }
    }

    /// The file offset nearest `offset`: a replacement's start or end, as
    /// the offset starts or ends a span.
    fn near(&self, offset: usize, end: bool) -> usize {
        match self.place(offset, end) {
            Place::Copied { at, .. } => at,
            Place::Replaced(index) if end => self.splices[index].source.end,
            Place::Replaced(index) => self.splices[index].source.start,
            Place::Added => self.source_len,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const SOURCE: &str = "test(\"a\") do\n  assert(x)\nend\n";
    const GENERATED: &str = "fn __test_body_0() do\n  assert(x)\nend\n\nfn main() do\nend\n";

    fn map() -> SourceMap {
        let header = SOURCE.find(" do").unwrap() + 3;
        SourceMap::new(SOURCE.len(), [(0..header, "fn __test_body_0() do".len())])
    }

    fn span_of(text: &str, needle: &str) -> Span {
        let start = text.find(needle).unwrap();
        Span::new(start as u32, (start + needle.len()) as u32)
    }

    #[test]
    fn copied_text_maps_exactly() {
        let at = map().origin(span_of(GENERATED, "x)"));
        assert_eq!(at, Origin::Exact(span_of(SOURCE, "x)")));
        let Origin::Exact(span) = at else {
            unreachable!()
        };
        assert_eq!(&SOURCE[span.start as usize..span.end as usize], "x)");
    }

    #[test]
    fn a_replacement_maps_near_what_it_replaced() {
        assert_eq!(
            map().origin(span_of(GENERATED, "__test_body_0")),
            Origin::Near(span_of(SOURCE, "test(\"a\") do"))
        );
        assert_eq!(
            map().origin(span_of(GENERATED, "do\n  assert")),
            Origin::Near(span_of(SOURCE, "test(\"a\") do\n  assert"))
        );
    }

    #[test]
    fn spans_at_a_replacements_edges_stay_in_the_copy() {
        let header = "fn __test_body_0() do".len() as u32;
        assert_eq!(
            map().origin(Span::new(header, header + 1)),
            Origin::Exact(span_of(SOURCE, "\n"))
        );
        assert_eq!(
            map().origin(Span::new(header, header)),
            Origin::Exact(Span::new(12, 12))
        );
        assert_eq!(map().origin(Span::new(0, 0)), Origin::Near(Span::new(0, 0)));
    }

    #[test]
    fn added_text_maps_to_the_end_of_the_file() {
        let end = SOURCE.len() as u32;
        assert_eq!(
            map().origin(span_of(GENERATED, "main")),
            Origin::Near(Span::new(end, end))
        );
        assert_eq!(
            map().origin(span_of(GENERATED, "end\n\nfn")),
            Origin::Near(Span::new(end - 4, end))
        );
    }

    #[test]
    fn an_identity_map_is_exact() {
        let identity = SourceMap::new(SOURCE.len(), []);
        assert_eq!(
            identity.origin(Span::new(3, 9)),
            Origin::Exact(Span::new(3, 9))
        );
    }
}
